test('lineDiscount with bulk discount: no bulk discount for qty < 10', () => {
  // qty 9, no bulk discount
  const line = { qty: 9, unitPrice: 1000, discountPercent: 10 };
  const lineTotal_ = 9 * 1000; // 9000
  const lineDiscount_ = 9000 * 10 / 100; // 900
  assert.equal(lineDiscount(line), 900);
