test('invoiceTotals with bulk discount: complex multi-line with various discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 15, unitPrice: 500, discountPercent: 5, vatRate: 9 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: qty 10, lineTotal = 10000
  //   lineDiscount = 1000
  //   bulkDiscount = 9000 * 2.5 / 100 = 225
  //   totalDiscount = 1225
  //   amountForVAT = 8775
  //   VAT = 8775 * 21 / 100 = 1842.75 → 1843
  // Line 2: qty 15, lineTotal = 7500
  //   lineDiscount = 7500 * 5 / 100 = 375
  //   bulkDiscount = 7125 * 2.5 / 100 = 178.125 → 178
  //   totalDiscount = 553
  //   amountForVAT = 6947
  //   VAT = 6947 * 9 / 100 = 625.23 → 625
  // Line 3: qty 5, lineTotal = 10000
  //   lineDiscount = 0
  //   bulkDiscount = 0 (qty < 10)
  //   totalDiscount = 0
  //   amountForVAT = 10000
  //   VAT = 0
  // Subtotal: 10000 + 7500 + 10000 = 27500
  // Total discount: 1225 + 553 + 0 = 1778
  // Total VAT: 1843 + 625 + 0 = 2468
  // Total: 27500 - 1778 + 2468 = 28190
  assert.equal(totals.subtotal, 27500);
  assert.equal(totals.discount, 1778);
  assert.equal(totals.vat, 2468);
  assert.equal(totals.total, 28190);
});

