  // lineDiscount = 9000 * 10 / 100 = 900
  // bulkDiscount = 0 (qty < 10)
  // totalDiscount = 900
  // amountForVAT = 9000 - 900 = 8100
  // VAT = 8100 * 21 / 100 = 1701
