test('invoiceTotals with bulk discount: multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 500, discountPercent: 0, vatRate: 21 }, // Has bulk discount
      { qty: 5, unitPrice: 500, discountPercent: 0, vatRate: 21 },  // No bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: qty 10, lineTotal = 5000
  //   lineDiscount = 0
  //   bulkDiscount = 5000 * 2.5 / 100 = 125
  //   totalDiscount = 125
  //   amountForVAT = 5000 - 125 = 4875
  //   VAT = 4875 * 21 / 100 = 1023.75 → 1024
  // Line 2: qty 5, lineTotal = 2500
  //   lineDiscount = 0
  //   bulkDiscount = 0 (qty < 10)
  //   totalDiscount = 0
  //   amountForVAT = 2500
  //   VAT = 2500 * 21 / 100 = 525
  // Subtotal: 5000 + 2500 = 7500
  // Total discount: 125 + 0 = 125
  // Total VAT: 1024 + 525 = 1549
  // Total: 7500 - 125 + 1549 = 8924
  assert.equal(totals.subtotal, 7500);
  assert.equal(totals.discount, 125);
  assert.equal(totals.vat, 1549);
  assert.equal(totals.total, 8924);
});

test('invoiceTotals with bulk discount: bulk discount with tier discount', () => {
