  // lineTotal = 10 * 1000 = 10000
  // lineDiscount = 10000 * 5 / 100 = 500
  // amountAfterLineDiscount = 10000 - 500 = 9500
  // bulkDiscount = 9500 * 2.5 / 100 = 237.5 → 238 (banker's rounding)
  // totalDiscount = 500 + 238 = 738
  // amountForVAT = 10000 - 738 = 9262
  // VAT = 9262 * 21 / 100 = 1945.02 → 1945
  // Total: 10000 - 738 + 1945 = 11207
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 738);
  assert.equal(totals.vat, 1945);
  assert.equal(totals.total, 11207);
});

test('invoiceTotals with bulk discount: bulk discount at exact boundary (qty = 10)', () => {
