  assert.equal(totals.discount, 25);
  assert.equal(totals.total, 975);
});

test('invoiceTotals with bulk discount: complex multi-line with various discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 15, unitPrice: 500, discountPercent: 5, vatRate: 9 },
