test('lineVAT with bulk discount: VAT on amount after both discounts', () => {
  // qty 10, unitPrice 100, discountPercent 10, vatRate 21
  // lineTotal = 10 * 100 = 1000
  // lineDiscount = 1000 * 10 / 100 = 100
  // amountAfterLineDiscount = 1000 - 100 = 900
  // bulkDiscount = 900 * 2.5 / 100 = 22.5 → 23 (banker's rounding)
  // amountForVAT = 1000 - 100 - 23 = 877
  // VAT = 877 * 21 / 100 = 184.17 → 184
  const line = { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line), 184);
});

test('lineVAT with bulk discount: qty >= 10 gets bulk discount', () => {
  // qty 10, unitPrice 1000, no line discount, vatRate 21
  // lineTotal = 10 * 1000 = 10000
  // lineDiscount = 0
  // bulkDiscount = 10000 * 2.5 / 100 = 250
  // amountForVAT = 10000 - 250 = 9750
  // VAT = 9750 * 21 / 100 = 2047.5 → 2048 (banker's rounding)
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  assert.equal(lineVAT(line), 2048);
});

test('lineVAT with bulk discount: qty < 10 no bulk discount', () => {
