      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // explicit 10%, vatRate 21
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, lineDiscount = 2125, bulkDiscount = 82875 * 2.5 / 100 = 2071.875 → 2072
  //   totalDiscount = 4197, amountForVAT = 80803, VAT = 80803 * 21 / 100 = 16968.63 → 16969
  // Line 2: 5 * 9500 = 47500, discount = 4750, no bulk (qty < 10), amountForVAT = 42750, VAT = 42750 * 21 / 100 = 8977.5 → 8978
  // Subtotal: 85000 + 47500 = 132500
  // Total discount: 4197 + 4750 = 8947
  // Total VAT: 16969 + 8978 = 25947
  // Total: 132500 - 8947 + 25947 = 149500
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 8947);
  assert.equal(totals.vat, 25947);
  assert.equal(totals.total, 149500);
});

