  //   VAT = 8775 * 21 / 100 = 1842.75 → 1843
  // Line 2: qty 15, lineTotal = 7500
  //   lineDiscount = 7500 * 5 / 100 = 375
  //   bulkDiscount = 7125 * 2.5 / 100 = 178.125 → 178
  //   totalDiscount = 553
  //   amountForVAT = 6947
  //   VAT = 6947 * 9 / 100 = 625.23 → 625
  // Line 3: qty 5, lineTotal = 10000
  //   lineDiscount = 0
  //   bulkDiscount = 0 (qty < 10)
  //   totalDiscount = 0
  //   amountForVAT = 10000
  //   VAT = 0
  // Subtotal: 10000 + 7500 + 10000 = 27500
  // Total discount: 1225 + 553 + 0 = 1778
  // Total VAT: 1843 + 625 + 0 = 2468
  // Total: 27500 - 1778 + 2468 = 28190
  assert.equal(totals.subtotal, 27500);
  assert.equal(totals.discount, 1778);
  assert.equal(totals.vat, 2468);
  assert.equal(totals.total, 28190);
});

