test('invoiceTotals includes VAT in calculation', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 10000, lineDiscount = 0, bulkDiscount = 10000 * 2.5 / 100 = 250
  // amountForVAT = 10000 - 250 = 9750
  // VAT = 9750 * 21 / 100 = 2047.5 → 2048
  // total = 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 100, vatRate: 21 }, // lineTotal 10000, bulk 250, VAT 2048
      { qty: 100, unitPrice: 100, vatRate: 9 },  // lineTotal 10000, bulk 250, VAT 878
      { qty: 100, unitPrice: 100, vatRate: 0 },  // lineTotal 10000, bulk 250, VAT 0
    ],
  };
  const totals = invoiceTotals(invoice);
  // Each line gets bulk discount = 250
  // Line 1: amountForVAT = 9750, VAT = 2048
  // Line 2: amountForVAT = 9750, VAT = 878
  // Line 3: amountForVAT = 9750, VAT = 0
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.discount, 750); // 250 * 3
  assert.equal(totals.vat, 2926); // 2048 + 878 + 0
  assert.equal(totals.total, 32176); // 30000 - 750 + 2926
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 10000, lineDiscount = 1000, bulkDiscount = 9000 * 2.5 / 100 = 225
  // totalDiscount = 1225, amountForVAT = 10000 - 1225 = 8775
  // VAT = 8775 * 21 / 100 = 1842.75 → 1843
  // total = 10000 - 1225 + 1843 = 10618
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10618);
});

test('invoiceTotals per-line VAT rounding with multiple lines', () => {
