const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
console.log('Example: 10 units @€100, no line discount, 21% VAT');
console.log('Line total:', lineTotal(line));
console.log('Line discount (includes bulk):', lineDiscount(line));
console.log('Line VAT:', lineVAT(line));

const invoice = { lines: [line] };
const totals = invoiceTotals(invoice);
console.log('');
console.log('Invoice totals:');
console.log('Subtotal:', totals.subtotal);
console.log('Discount (line + bulk):', totals.discount);
console.log('VAT:', totals.vat);
console.log('Total:', totals.total);
